#pragma once

namespace uta {

inline constexpr char kWebPage[] = R"UTA(<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>UTA-robot — Bảng điều khiển</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf3f8;color:#172c3e;font:16px system-ui;line-height:1.5}main{max-width:1040px;margin:auto;padding:20px}h1{margin:8px 0}h2{font-size:21px;margin:0 0 12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}section{background:white;border-radius:14px;padding:20px;margin-bottom:16px;border:1px solid #d9e4ee}label{display:block;margin:12px 0 5px}input,select,button{font:inherit;border-radius:8px;padding:10px;border:1px solid #bacbd9}input,select{width:100%}button{background:#174e78;color:white;cursor:pointer;margin:6px 3px 0 0;touch-action:none}button:disabled{opacity:.5}.danger{background:#ab3038}.pad{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;max-width:320px;margin:auto}.pad button{min-height:60px}.hint{font-size:14px;color:#4b657a}#thongbao{position:sticky;top:0;padding:12px;border-radius:8px;background:#dceaf6;z-index:2;white-space:pre-wrap}.error{background:#ffe1df!important}table{width:100%;border-collapse:collapse}td{padding:7px;border-bottom:1px solid #e3eaf0}td input{width:90px}details{margin-top:12px}a{color:#174e78}
</style></head><body><main><h1>UTA-robot</h1><p>Điều khiển robot, nghe nhạc và cài đặt thiết bị</p>
<p id="thongbao" role="status" aria-live="polite">Đang đọc trạng thái thiết bị…</p>
<div class="grid"><section id="dieukhienrobot" hidden><h2>Di chuyển</h2><p class="hint">Giữ nút để chạy, thả để dừng. Robot tự dừng khi mất lệnh điều khiển.</p>
<div class="pad"><span></span><button data-huong="tien">Tiến</button><span></span><button data-huong="trai">Trái</button><button id="dungrobot" class="danger">Dừng</button><button data-huong="phai">Phải</button><span></span><button data-huong="lui">Lùi</button><span></span></div>
<div id="phukienuart"><button id="nhay">Nhảy múa</button><label for="den">Hiệu ứng đèn</label><select id="den"><option value="1">Sáng thường</option><option value="2">Nhấp nháy</option><option value="3">Sáng dịu chậm</option><option value="4">Sáng dịu nhanh</option><option value="5">Chuyển màu</option><option value="6">Trình diễn</option></select><button id="doiden">Đổi hiệu ứng</button></div></section>
<section><h2>Nhạc trực tuyến</h2><label for="baihat">Tên bài hát</label><input id="baihat" maxlength="160" placeholder="Nhập tên bài hát"><label for="casi">Ca sĩ</label><input id="casi" maxlength="160" placeholder="Có thể để trống"><button id="phatnhac">Tìm và phát</button>
<p id="trangthainhac">Đã dừng</p><button id="tamdung">Tạm dừng</button><button id="tieptuc">Tiếp tục</button><button id="dungnhac">Dừng nhạc</button><label for="amluong">Âm lượng</label><input id="amluong" type="range" min="0" max="100" value="60"><label for="dosang">Độ sáng màn hình</label><input id="dosang" type="range" min="5" max="100" value="80"></section></div>
<section id="dieukhienservo" hidden><h2>Đầu và cổ</h2><label for="gocdau">Góc đầu</label><input id="gocdau" type="range" min="15" max="165" value="90"><button id="daugiua">Đầu về giữa</button><label for="gocco">Góc cổ</label><input id="gocco" type="range" min="15" max="165" value="90"><button id="cogiua">Cổ về giữa</button></section>
<section><h2>Phát video MP4</h2><label for="urlvideo">Địa chỉ tệp MP4 trực tiếp</label><input id="urlvideo" type="url" maxlength="512" placeholder="https://may-chu/video.mp4"><p class="hint">Phát hình và tiếng trên thiết bị. Dùng H.264 Baseline hoặc MJPEG, tối đa 240×240, 15 hình/giây; âm thanh AAC-LC hoặc MP3. Máy chủ cần hỗ trợ tải từng phần. Không dùng liên kết trang xem video.</p><button id="phatvideo">Phát video trên thiết bị</button><p class="hint">Dùng các nút tạm dừng, tiếp tục và dừng ở phần nhạc. Phổ nhạc hiển thị trên màn hình khi nghe nhạc hoặc radio.</p></section>
<section><h2>Đài phát thanh Internet</h2><p class="hint">Các đài cần kết nối mạng. Đây không phải bộ thu sóng FM bằng anten.</p><label for="dai">Chọn đài</label><select id="dai"></select><button id="phatdai">Phát đài đã chọn</button><button id="phattuychinh">Phát đài tùy chỉnh đã lưu</button></section>
<section><h2>Cài đặt âm thanh và truy cập</h2><form id="caidat"><label for="maychu">URL máy chủ nhạc có thể thay đổi</label><input id="maychu" type="url" maxlength="512" placeholder="https://may-chu-cua-ban"><p class="hint">Máy chủ cần hỗ trợ tìm bài theo giao thức của repo IoT Việt Nam. Có thể thay máy chủ khác cùng giao thức, địa chỉ được lưu sau khi tắt nguồn. Không cần nạp lại firmware.</p>
<label for="khoanhac">Khóa máy chủ nhạc</label><input id="khoanhac" type="password" maxlength="128" autocomplete="off" placeholder="Để trống để giữ khóa hiện tại"><label for="tendai">Tên đài tùy chỉnh</label><input id="tendai" maxlength="120"><label for="urldai">Địa chỉ luồng đài tùy chỉnh</label><input id="urldai" type="url" maxlength="512"><label for="matkhau">Mật khẩu web mới</label><input id="matkhau" type="password" minlength="8" maxlength="64" autocomplete="new-password" placeholder="Để trống để giữ mật khẩu hiện tại">
<details><summary>Cài đặt GPIO và cảm ứng</summary><p class="hint">Có thể đổi chân mic INMP441, loa MAX98357 và màn hình ST7789. Giữ các chân khởi động, bộ nhớ và USB. Chỉ đổi các chân được phép; không dùng một chân cho hai chức năng. Giá trị -1 chỉ hợp lệ cho đặt lại màn hình hoặc ngắt cảm ứng.</p><label><input id="camung" type="checkbox" style="width:auto"> Bật cảm ứng XPT2046 đã đấu dây</label><label><input id="robotuart" type="checkbox" style="width:auto"> Bật bộ điều khiển robot qua UART tương thích lệnh x/y, d, w</label><label for="driverdc">Driver cho hai động cơ N20</label><select id="driverdc"><option value="0">Tắt động cơ trực tiếp</option><option value="1">L298N</option><option value="2">DRV8833</option></select><label for="tocdodc">Tốc độ động cơ (%)</label><input id="tocdodc" type="number" min="1" max="100" value="60"><label><input id="daotrai" type="checkbox" style="width:auto"> Đảo chiều động cơ trái</label><label><input id="daophai" type="checkbox" style="width:auto"> Đảo chiều động cơ phải</label><label><input id="batservo" type="checkbox" style="width:auto"> Bật hai servo 180 độ cho đầu và cổ</label>
<p class="hint">L298N: tháo cầu nối ENA/ENB để điều tốc. DRV8833: chỉ dùng bốn chân IN, đưa nSLEEP lên mức bật. Chọn động cơ trực tiếp thì tắt UART. Servo dùng nguồn riêng phù hợp, nối chung GND.</p>
<label>Đầu: góc nhỏ nhất / lớn nhất / giữa</label><input id="min0" type="number" min="0" max="180" value="15"><input id="max0" type="number" min="0" max="180" value="165"><input id="nha0" type="number" min="0" max="180" value="90"><label>Cổ: góc nhỏ nhất / lớn nhất / giữa</label><input id="min1" type="number" min="0" max="180" value="15"><input id="max1" type="number" min="0" max="180" value="165"><input id="nha1" type="number" min="0" max="180" value="90">
<table><tbody id="bangchan"></tbody></table><p class="hint">GPIO chỉ áp dụng sau khi khởi động lại. Hãy đấu lại dây theo cấu hình trước lần khởi động đó.</p></details><button type="submit">Lưu cài đặt</button></form></section>
<section><h2>Thiết bị</h2><button id="khoidonglai">Khởi động lại</button><button id="cauhinhwifi">Cấu hình lại Wi-Fi</button><p class="hint">Tài khoản đăng nhập: uta. Nhấn BOOT ba lần để hiện lại địa chỉ và mật khẩu trên màn hình.</p></section>
</main><script>
let duLieu=null,giuNut=null,dangGui=false;const el=id=>document.getElementById(id);
function thongBao(noiDung,loi=false){el('thongbao').textContent=noiDung;el('thongbao').classList.toggle('error',loi)}
async function yeuCau(duongDan,noiDung){const tuyChon=noiDung?{method:'POST',headers:{'Content-Type':'application/json','X-UTA-Yeu-Cau':'1'},body:JSON.stringify(noiDung)}:{};const boDieuKhien=new AbortController(),henGio=setTimeout(()=>boDieuKhien.abort(),6000);let phanHoi;try{phanHoi=await fetch(duongDan,{...tuyChon,cache:'no-store',signal:boDieuKhien.signal})}catch{throw Error('Không kết nối được với thiết bị. Hãy kiểm tra Wi-Fi và thử lại.')}finally{clearTimeout(henGio)}if(phanHoi.status===401)throw Error('Phiên đăng nhập đã hết hiệu lực. Hãy tải lại trang và đăng nhập lại.');let data;try{data=await phanHoi.json()}catch{throw Error('Thiết bị trả về dữ liệu không hợp lệ.')}if(!phanHoi.ok)throw Error(data.thong_bao||'Không thực hiện được yêu cầu.');return data}
async function lenh(ten,thamSo={}){try{const data=await yeuCau('/api/lenh',{lenh:ten,...thamSo});thongBao(data.thong_bao);return true}catch(e){thongBao(e.message,true);return false}}
async function capNhat(dau=false){try{const data=await yeuCau('/api/trang-thai');el('trangthainhac').textContent=data.trang_thai_nhac;if(dau){duLieu=data;el('maychu').value=data.may_chu_nhac;el('tendai').value=data.ten_radio;el('urldai').value=data.url_radio;el('camung').checked=data.cam_ung;el('robotuart').checked=data.robot_uart;el('dieukhienrobot').hidden=!data.robot_dang_bat;el('phukienuart').hidden=!data.uart_dang_bat;el('dieukhienservo').hidden=!data.servo_dang_bat;el('driverdc').value=data.driver_dc;el('tocdodc').value=data.toc_do_dc;el('daotrai').checked=data.dao_dc_trai;el('daophai').checked=data.dao_dc_phai;el('batservo').checked=data.bat_servo;for(let i=0;i<2;i++){el('min'+i).value=data['goc_min_'+i];el('max'+i).value=data['goc_max_'+i];el('nha'+i).value=data['goc_nha_'+i];const o=el(i?'gocco':'gocdau');o.min=data['dang_min_'+i];o.max=data['dang_max_'+i];o.value=data['dang_nha_'+i]}el('dai').replaceChildren();data.danh_sach_dai.forEach(d=>el('dai').add(new Option(d.ten,d.ma)));el('bangchan').replaceChildren();data.chan.forEach(c=>{const hang=document.createElement('tr'),nhan=document.createElement('td'),o=document.createElement('td'),input=document.createElement('input');nhan.textContent=c.ten;input.type='number';input.min='-1';input.max='48';input.required=true;input.value=c.gia_tri;input.dataset.chan=c.ma;o.append(input);hang.append(nhan,o);el('bangchan').append(hang)});thongBao(data.can_khoi_dong_lai?'Cài đặt chân đang chờ khởi động lại.':'Đã kết nối với UTA-robot.')}}catch(e){thongBao(e.message,true)}}
function dung(){if(giuNut){clearInterval(giuNut);giuNut=null;lenh('robot',{huong:'dung',thoi_gian:100})}}
document.querySelectorAll('[data-huong]').forEach(nut=>{nut.onpointerdown=e=>{e.preventDefault();dung();nut.setPointerCapture(e.pointerId);const gui=async()=>{if(dangGui)return;dangGui=true;try{await lenh('robot',{huong:nut.dataset.huong,thoi_gian:600})}finally{dangGui=false}};gui();giuNut=setInterval(gui,250)};nut.onpointerup=nut.onpointercancel=nut.onlostpointercapture=dung});window.addEventListener('blur',dung);document.addEventListener('visibilitychange',()=>{if(document.hidden)dung()});el('dungrobot').onclick=()=>{dung();lenh('robot',{huong:'dung',thoi_gian:100})};
el('nhay').onclick=()=>lenh('robot',{huong:'nhay',thoi_gian:2000});el('doiden').onclick=()=>lenh('robot',{huong:'den',thoi_gian:Number(el('den').value)});el('phatnhac').onclick=()=>lenh('nhac',{bai_hat:el('baihat').value,ca_si:el('casi').value});el('phatdai').onclick=()=>lenh('radio',{ma_dai:el('dai').value});el('phattuychinh').onclick=()=>lenh('radio',{ma_dai:'tuy_chinh'});el('tamdung').onclick=()=>lenh('tam_dung');el('tieptuc').onclick=()=>lenh('tiep_tuc');el('dungnhac').onclick=()=>lenh('dung_nhac');el('amluong').onchange=()=>lenh('am_luong',{gia_tri:Number(el('amluong').value)});el('dosang').onchange=()=>lenh('do_sang',{gia_tri:Number(el('dosang').value)});
el('phatvideo').onclick=()=>lenh('video',{url:el('urlvideo').value});el('gocdau').onchange=()=>lenh('servo',{truc:0,goc:Number(el('gocdau').value)});el('gocco').onchange=()=>lenh('servo',{truc:1,goc:Number(el('gocco').value)});el('daugiua').onclick=()=>{el('gocdau').value=duLieu.dang_nha_0;el('gocdau').onchange()};el('cogiua').onclick=()=>{el('gocco').value=duLieu.dang_nha_1;el('gocco').onchange()};
el('caidat').onsubmit=async e=>{e.preventDefault();const chan={};document.querySelectorAll('[data-chan]').forEach(x=>chan[x.dataset.chan]=Number(x.value));const dongCo={driver_dc:Number(el('driverdc').value),toc_do_dc:Number(el('tocdodc').value),dao_dc_trai:el('daotrai').checked,dao_dc_phai:el('daophai').checked,bat_servo:el('batservo').checked};for(let i=0;i<2;i++){dongCo['goc_min_'+i]=Number(el('min'+i).value);dongCo['goc_max_'+i]=Number(el('max'+i).value);dongCo['goc_nha_'+i]=Number(el('nha'+i).value)}try{const data=await yeuCau('/api/cai-dat',{may_chu_nhac:el('maychu').value,khoa_nhac:el('khoanhac').value,ten_radio:el('tendai').value,url_radio:el('urldai').value,mat_khau_moi:el('matkhau').value,cam_ung:el('camung').checked,robot_uart:el('robotuart').checked,chan,...dongCo});el('khoanhac').value='';el('matkhau').value='';thongBao(data.thong_bao)}catch(err){thongBao(err.message,true)}};
el('khoidonglai').onclick=()=>{if(confirm('Khởi động lại UTA-robot và áp dụng sơ đồ chân đã lưu?'))lenh('khoi_dong_lai')};el('cauhinhwifi').onclick=()=>{if(confirm('Dừng phát nhạc và mở chế độ cấu hình Wi-Fi?'))lenh('cau_hinh_wifi')};capNhat(true);setInterval(()=>capNhat(false),3000);
</script></body></html>)UTA";

}  // namespace uta
